using System.Collections.Generic;
using UnityEngine;

// Intermediate project, ① Geometry Modeling.
// Both meshes are generated by code; all circular vertex positions are computed using for loops.
public static class Mid_MoonGardenV3Meshes
{
    public enum Kind { LotusLantern, StarCrystal, MoonHalo }

    public static Mesh Build(Kind kind)
    {
        return kind == Kind.LotusLantern ? MakeLotusLantern(12) :
               kind == Kind.StarCrystal ? MakeStarCrystal(8) : MakeMoonHalo(72, 8);
    }

    public static Mesh MakeLotusLantern(int segments)
    {
        segments = Mathf.Max(6, segments);
        // The lantern grows outwards, narrows at the neck, then tapers into a crown.
        float[] levels = { -0.56f, -0.39f, -0.12f, 0.18f, 0.46f, 0.58f };
        float[] radii  = {  0.13f,  0.42f,  0.55f, 0.46f, 0.28f, 0.10f };
        var vertices = new List<Vector3>();
        var uv = new List<Vector2>();
        var tris = new List<int>();
        for (int ring = 0; ring < levels.Length; ring++)
        {
            for (int i = 0; i <= segments; i++)
            {
                float a = i * 2f * Mathf.PI / segments;
                float petal = 1f + 0.075f * Mathf.Cos(a * 6f + ring * 0.35f);
                vertices.Add(new Vector3(Mathf.Cos(a) * radii[ring] * petal,
                                         levels[ring],
                                         Mathf.Sin(a) * radii[ring] * petal));
                uv.Add(new Vector2((float)i / segments, (float)ring / (levels.Length - 1)));
            }
        }
        int stride = segments + 1;
        for (int ring = 0; ring < levels.Length - 1; ring++)
        {
            for (int i = 0; i < segments; i++)
            {
                int a = ring * stride + i;
                int b = a + stride;
                tris.Add(a); tris.Add(b); tris.Add(a + 1);
                tris.Add(a + 1); tris.Add(b); tris.Add(b + 1);
            }
        }
        var mesh = new Mesh { name = "MP_LotusLantern_Procedural" };
        mesh.SetVertices(vertices);
        mesh.SetUVs(0, uv);
        mesh.SetTriangles(tris, 0);
        mesh.RecalculateNormals();
        mesh.RecalculateBounds();
        return mesh;
    }

    public static Mesh MakeStarCrystal(int sides)
    {
        sides = Mathf.Max(5, sides);
        // An elongated faceted crystal: two tips + two multi-sided rings.
        // Each face uses duplicated vertices to give the crystal sharp, flat facets.
        var vertices = new List<Vector3>();
        var uv = new List<Vector2>();
        var triangles = new List<int>();
        Vector3 top = new Vector3(0, 0.85f, 0);
        Vector3 bottom = new Vector3(0, -0.78f, 0);
        for (int i = 0; i < sides; i++)
        {
            float a0 = i * 2f * Mathf.PI / sides;
            float a1 = (i + 1) * 2f * Mathf.PI / sides;
            float offset = Mathf.PI / sides;
            Vector3 m0 = new Vector3(Mathf.Cos(a0) * .34f, .1f, Mathf.Sin(a0) * .34f);
            Vector3 m1 = new Vector3(Mathf.Cos(a1) * .34f, .1f, Mathf.Sin(a1) * .34f);
            Vector3 l0 = new Vector3(Mathf.Cos(a0 + offset) * .23f, -.35f, Mathf.Sin(a0 + offset) * .23f);
            Vector3 l1 = new Vector3(Mathf.Cos(a1 + offset) * .23f, -.35f, Mathf.Sin(a1 + offset) * .23f);
            AddTriangle(vertices, uv, triangles, top, m1, m0);
            AddTriangle(vertices, uv, triangles, m0, m1, l0);
            AddTriangle(vertices, uv, triangles, l0, m1, l1);
            AddTriangle(vertices, uv, triangles, bottom, l0, l1);
        }
        var mesh = new Mesh { name = "MP_StarCrystal_Procedural" };
        mesh.SetVertices(vertices); mesh.SetUVs(0, uv);
        mesh.SetTriangles(triangles, 0);
        mesh.RecalculateNormals(); mesh.RecalculateBounds();
        return mesh;
    }

    // Third procedural geometry: a glowing moon-gate torus, built from nested loops.
    public static Mesh MakeMoonHalo(int segments, int tubeSegments)
    {
        var vertices = new List<Vector3>();
        var uv = new List<Vector2>();
        var triangles = new List<int>();
        for (int ring = 0; ring <= segments; ring++)
        {
            float u = ring * 2f * Mathf.PI / segments;
            for (int j = 0; j <= tubeSegments; j++)
            {
                float v = j * 2f * Mathf.PI / tubeSegments;
                float radius = 1.02f + .045f * Mathf.Cos(v);
                vertices.Add(new Vector3(radius * Mathf.Cos(u),
                                         radius * Mathf.Sin(u),
                                         .045f * Mathf.Sin(v)));
                uv.Add(new Vector2((float)ring / segments, (float)j / tubeSegments));
            }
        }
        int stride = tubeSegments + 1;
        for (int ring = 0; ring < segments; ring++)
            for (int j = 0; j < tubeSegments; j++)
            {
                int a = ring * stride + j;
                triangles.Add(a); triangles.Add(a + stride); triangles.Add(a + 1);
                triangles.Add(a + 1); triangles.Add(a + stride); triangles.Add(a + stride + 1);
            }
        var mesh = new Mesh { name = "MP_MoonGate_Torus_Procedural" };
        mesh.SetVertices(vertices); mesh.SetUVs(0, uv);
        mesh.SetTriangles(triangles, 0);
        mesh.RecalculateNormals(); mesh.RecalculateBounds();
        return mesh;
    }

    static void AddTriangle(List<Vector3> vertices, List<Vector2> uv, List<int> tris,
                            Vector3 a, Vector3 b, Vector3 c)
    {
        int i = vertices.Count;
        vertices.Add(a); vertices.Add(b); vertices.Add(c);
        uv.Add(new Vector2(.5f, 1f)); uv.Add(new Vector2(1f, 0f)); uv.Add(new Vector2(0f, 0f));
        tris.Add(i); tris.Add(i + 1); tris.Add(i + 2);
    }
}
